import { useState } from 'react'
import VoiceInput from './VoiceInput.jsx'
import { createProduct, updateProduct, imageUrl } from '../services/api.js'
import { useAuth } from '../services/AuthContext.jsx'
import { CRAFT_CATEGORIES } from '../constants.js'

// Handles both "Add Product" and "Edit Product" - if an existing
// product is passed in, its values pre-fill the form and Save calls
// the update endpoint instead of create.
export default function ProductForm({ existingProduct, onSaved, onCancel }) {
  const { token, user } = useAuth()
  const language = user?.preferred_language || 'Hindi'
  const [form, setForm] = useState({
    name: existingProduct?.name || '',
    name_hindi: existingProduct?.name_hindi || '',
    description_english: existingProduct?.description_english || '',
    description_hindi: existingProduct?.description_hindi || '',
    material: existingProduct?.material || '',
    category: existingProduct?.category || CRAFT_CATEGORIES[0],
    craft_type: existingProduct?.craft_type || '',
    price: existingProduct?.price ?? '',
  })
  const [imageFile, setImageFile] = useState(null)
  const [preview, setPreview] = useState(imageUrl(existingProduct?.image_url))
  const [error, setError] = useState('')
  const [loading, setLoading] = useState(false)

  function handleChange(e) {
    setForm({ ...form, [e.target.name]: e.target.value })
  }

  // Adds a spoken phrase to the end of a field instead of replacing it,
  // so the artisan can dictate in several short bursts.
  function appendSpoken(field, text) {
    setForm((current) => ({
      ...current,
      [field]: current[field] ? `${current[field]} ${text}` : text,
    }))
  }

  function handleImageChange(e) {
    const file = e.target.files?.[0]
    if (!file) return
    setImageFile(file)
    setPreview(URL.createObjectURL(file))
  }

  async function save(status) {
    setError('')
    setLoading(true)
    try {
      const formData = new FormData()
      Object.entries(form).forEach(([key, value]) => formData.append(key, value ?? ''))
      formData.append('status', status)
      if (imageFile) formData.append('image', imageFile)

      const saved = existingProduct
        ? await updateProduct(existingProduct.id, formData, token)
        : await createProduct(formData, token)

      onSaved(saved)
    } catch (err) {
      setError(err.message)
    } finally {
      setLoading(false)
    }
  }

  const inputClass =
    'w-full p-3 rounded-lg border border-gray-300 focus:border-forest focus:outline-none text-base'
  const labelClass = 'block text-sm font-medium text-charcoal mb-1 mt-4'

  return (
    <div className="p-5">
      <h2 className="text-lg font-semibold text-forest mb-4">
        {existingProduct ? 'Edit Product' : 'Add Product'}
      </h2>

      <label className={labelClass}>Product Photo</label>
      {preview && (
        <img src={preview} alt="Product preview" className="w-full h-48 object-cover rounded-lg mb-2" />
      )}
      <input type="file" accept="image/jpeg,image/png,image/webp" onChange={handleImageChange} className="text-sm" />

      <label className={labelClass}>Product Name (English)</label>
      <input className={inputClass} name="name" value={form.name} onChange={handleChange} required />

      <label className={labelClass}>Product Name ({language})</label>
      <input
        className={inputClass}
        name="name_hindi"
        value={form.name_hindi}
        onChange={handleChange}
        placeholder="Speak it instead of typing (optional)"
      />
      <VoiceInput
        language={language}
        label="Speak the name"
        showLanguagePicker={false}
        onTranscript={(t) => appendSpoken('name_hindi', t)}
        className="mt-2"
      />

      <label className={labelClass}>Description (English)</label>
      <textarea className={inputClass} name="description_english" rows={3} value={form.description_english} onChange={handleChange} />
      <VoiceInput
        language="English"
        label="Speak in English"
        showLanguagePicker={false}
        onTranscript={(t) => appendSpoken('description_english', t)}
        className="mt-2"
      />

      <label className={labelClass}>Description ({language})</label>
      <textarea
        className={inputClass}
        name="description_hindi"
        rows={3}
        value={form.description_hindi}
        onChange={handleChange}
        placeholder="Speak it instead of typing (optional)"
      />
      <VoiceInput
        language={language}
        label="Speak the description"
        onTranscript={(t) => appendSpoken('description_hindi', t)}
        className="mt-2"
      />

      <label className={labelClass}>Category</label>
      <select className={inputClass} name="category" value={form.category} onChange={handleChange}>
        {CRAFT_CATEGORIES.map((c) => <option key={c} value={c}>{c}</option>)}
      </select>

      <label className={labelClass}>Material</label>
      <input className={inputClass} name="material" value={form.material} onChange={handleChange} placeholder="e.g. Wood, Cotton, Clay" />

      <label className={labelClass}>Craft Type</label>
      <input className={inputClass} name="craft_type" value={form.craft_type} onChange={handleChange} placeholder="e.g. Hand-carved, Hand-woven" />

      <label className={labelClass}>Price (₹)</label>
      <input className={inputClass} type="number" min="0" name="price" value={form.price} onChange={handleChange} />

      {error && <p className="text-red-600 text-sm mt-4">{error}</p>}

      <div className="flex gap-3 mt-6">
        <button
          onClick={() => save('draft')}
          disabled={loading || !form.name}
          className="flex-1 border border-forest text-forest font-semibold py-3 rounded-full disabled:opacity-60"
        >
          Save Draft
        </button>
        <button
          onClick={() => save('published')}
          disabled={loading || !form.name}
          className="flex-1 bg-terracotta text-white font-semibold py-3 rounded-full shadow-md disabled:opacity-60"
        >
          Publish
        </button>
      </div>
      <button onClick={onCancel} className="w-full text-gray-500 mt-3 py-2">
        Cancel
      </button>
    </div>
  )
}

import { useEffect, useState } from 'react'
import { listProducts } from '../services/api.js'
import { useAuth } from '../services/AuthContext.jsx'

// A shared "pick which of your products this applies to" dropdown -
// used by both the AI Photo Studio and the AI Catalogue screens, since
// both features enhance/describe one specific product at a time.
export default function ProductPicker({ selectedId, onSelect }) {
  const { token } = useAuth()
  const [products, setProducts] = useState([])
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    listProducts(token)
      .then((data) => {
        setProducts(data)
        if (data.length > 0 && !selectedId) onSelect(data[0])
      })
      .finally(() => setLoading(false))
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  if (loading) return <p className="text-gray-500 p-5">Loading your products...</p>

  if (products.length === 0) {
    return (
      <div className="p-5 text-center text-gray-500">
        <p className="mb-2">You need to add a product first.</p>
        <a href="/products" className="text-forest underline font-medium">Go to My Products</a>
      </div>
    )
  }

  return (
    <div className="p-5 pb-0">
      <label className="block text-sm font-medium text-charcoal mb-1">Select Product</label>
      <select
        className="w-full p-3 rounded-lg border border-gray-300 text-base"
        value={selectedId || ''}
        onChange={(e) => onSelect(products.find((p) => p.id === Number(e.target.value)))}
      >
        {products.map((p) => (
          <option key={p.id} value={p.id}>{p.name}</option>
        ))}
      </select>
    </div>
  )
}

import { useEffect, useRef, useState } from 'react'

/**
 * A reusable "speak instead of typing" button.
 *
 * Why this exists: typing Hindi on a phone means installing and learning a
 * Devanagari keyboard, which is a genuine barrier for the artisans this app
 * is built for. Speaking is instant and needs nothing extra. This uses the
 * browser's built-in Web Speech API, so it is completely free and needs no
 * backend, no API key and no app install.
 *
 * Usage:
 *   <VoiceInput language="Hindi" onTranscript={(text) => append(text)} />
 *
 * onTranscript is called with each newly finished phrase, so the parent can
 * decide whether to append it or replace what is there.
 */

// The browser expects locale codes, not language names.
const LOCALES = {
  Hindi: 'hi-IN',
  // Hinglish is Hindi spoken with English words mixed in, written in Roman
  // letters. There is no "hinglish" locale, and hi-IN would return
  // Devanagari, so en-IN is the correct choice - it is trained on Indian
  // accents and returns Roman script, which is exactly what Hinglish is.
  Hinglish: 'en-IN',
  English: 'en-IN',
  Bengali: 'bn-IN',
  Tamil: 'ta-IN',
  Telugu: 'te-IN',
  Marathi: 'mr-IN',
  Gujarati: 'gu-IN',
  Punjabi: 'pa-IN',
  Kannada: 'kn-IN',
  Malayalam: 'ml-IN',
  Odia: 'or-IN',
}

export function speechLocaleFor(language) {
  return LOCALES[language] || 'hi-IN'
}

export const SPEECH_SUPPORTED =
  typeof window !== 'undefined' &&
  Boolean(window.SpeechRecognition || window.webkitSpeechRecognition)

// Friendly explanations instead of raw browser error codes.
const ERROR_MESSAGES = {
  'not-allowed': 'Microphone blocked. Allow microphone access for this site and try again.',
  'service-not-allowed': 'Microphone blocked by your browser settings.',
  'no-speech': "Didn't catch that — please speak a little louder.",
  'audio-capture': 'No microphone found. Please check your device.',
  network: 'Voice typing needs an internet connection.',
}

export default function VoiceInput({
  onTranscript,
  language = 'Hindi',
  showLanguagePicker = true,
  label = 'Speak',
  className = '',
}) {
  const [locale, setLocale] = useState(speechLocaleFor(language))
  const [listening, setListening] = useState(false)
  const [interim, setInterim] = useState('')
  const [error, setError] = useState('')
  const recognitionRef = useRef(null)

  // If the artisan changes their language elsewhere, follow it.
  useEffect(() => {
    setLocale(speechLocaleFor(language))
  }, [language])

  // Never leave the microphone running when the screen closes.
  useEffect(() => {
    return () => {
      try {
        recognitionRef.current?.stop()
      } catch {
        /* already stopped */
      }
    }
  }, [])

  function start() {
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition
    if (!SpeechRecognition) return

    setError('')
    setInterim('')

    const recognition = new SpeechRecognition()
    recognition.lang = locale
    recognition.continuous = true
    recognition.interimResults = true

    recognition.onresult = (event) => {
      let live = ''
      // Only send phrases the browser has finalised; show the rest as a
      // live preview so the user can see it is hearing them.
      for (let i = event.resultIndex; i < event.results.length; i++) {
        const result = event.results[i]
        const text = result[0].transcript
        if (result.isFinal) {
          const clean = text.trim()
          if (clean) onTranscript?.(clean)
        } else {
          live += text
        }
      }
      setInterim(live)
    }

    recognition.onerror = (event) => {
      setError(ERROR_MESSAGES[event.error] || 'Voice typing stopped. Please try again.')
      setListening(false)
    }

    recognition.onend = () => {
      setListening(false)
      setInterim('')
    }

    try {
      recognition.start()
      recognitionRef.current = recognition
      setListening(true)
    } catch {
      setError('Could not start the microphone. Please try again.')
    }
  }

  function stop() {
    try {
      recognitionRef.current?.stop()
    } catch {
      /* already stopped */
    }
    setListening(false)
  }

  if (!SPEECH_SUPPORTED) {
    return (
      <p className={`text-xs text-gray-500 ${className}`}>
        Voice typing isn't supported in this browser. Chrome or Edge support it — for now,
        please type instead.
      </p>
    )
  }

  return (
    <div className={className}>
      <div className="flex gap-2 items-center">
        {showLanguagePicker && (
          <select
            className="p-2 rounded-lg border border-gray-300 text-sm"
            value={locale}
            onChange={(e) => setLocale(e.target.value)}
            disabled={listening}
            aria-label="Speaking language"
          >
            <option value="hi-IN">हिंदी</option>
            <option value="en-IN">English / Hinglish</option>
            <option value="bn-IN">বাংলা</option>
            <option value="ta-IN">தமிழ்</option>
            <option value="te-IN">తెలుగు</option>
            <option value="mr-IN">मराठी</option>
            <option value="gu-IN">ગુજરાતી</option>
            <option value="pa-IN">ਪੰਜਾਬੀ</option>
            <option value="kn-IN">ಕನ್ನಡ</option>
            <option value="ml-IN">മലയാളം</option>
            <option value="or-IN">ଓଡ଼ିଆ</option>
          </select>
        )}

        <button
          type="button"
          onClick={listening ? stop : start}
          className={`flex-1 rounded-full font-semibold py-2 px-4 text-sm transition-colors ${
            listening ? 'bg-red-500 text-white animate-pulse' : 'bg-forest text-white'
          }`}
        >
          {listening ? '⏹ Stop' : `🎙️ ${label}`}
        </button>
      </div>

      {listening && (
        <p className="text-xs text-forest mt-1">
          Listening… {interim && <span className="italic text-gray-500">{interim}</span>}
        </p>
      )}
      {error && <p className="text-xs text-red-600 mt-1">{error}</p>}
    </div>
  )
}

@tailwind base;
@tailwind components;
@tailwind utilities;

body {
  margin: 0;
  font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
  background-color: #FBE8DC; /* warm peach-cream - matches the 'ivory' token in tailwind.config.js */
  color: #252525;
}

/* Hide the scrollbar on horizontally-swipeable strips (category showcase,
   quick-access circles, recent products reel) so they read as a swipeable
   row of content instead of a boxy list with a visible scrollbar - closer
   to how a social-feed app usually looks. The content is still fully
   scrollable, just without the visible bar. */
.no-scrollbar {
  -ms-overflow-style: none;
  scrollbar-width: none;
}
.no-scrollbar::-webkit-scrollbar {
  display: none;
}

/* Continuously-scrolling "Discover" strip on the Dashboard - the feature
   list is rendered twice back to back and slid left by exactly one set's
   width (-50%), so the loop point is invisible and it never stops moving,
   unlike the touch-scrollable strips above which only move when swiped. */
@keyframes marquee {
  from { transform: translateX(0); }
  to { transform: translateX(-50%); }
}
.marquee-track {
  animation: marquee 26s linear infinite;
  width: max-content;
}
.marquee-track:hover {
  animation-play-state: paused;
}

/* --- Premium polish: entrance animation + skeleton loaders ---------- */

/* Gentle fade-up used on cards/sections as real data replaces loading
   state, so content doesn't just "pop in" - a small, cheap touch that
   reads as a more finished, native-app-like UI. */
@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}
.fade-in {
  animation: fadeInUp 0.35s ease-out both;
}

/* Shimmering grey block standing in for content that hasn't loaded yet,
   instead of a plain "Loading..." line - used for stat cards, the AI
   insight card, and product thumbnails while their real data is fetched. */
@keyframes shimmer {
  0% { background-position: -200% 0; }
  100% { background-position: 200% 0; }
}
.skeleton {
  background: linear-gradient(90deg, #e9e5df 25%, #f4f1ec 37%, #e9e5df 63%);
  background-size: 400% 100%;
  animation: shimmer 1.4s ease infinite;
}

import React from 'react'
import ReactDOM from 'react-dom/client'
import { BrowserRouter } from 'react-router-dom'
import App from './App.jsx'
import { AuthProvider } from './services/AuthContext.jsx'
import './index.css'

ReactDOM.createRoot(document.getElementById('root')).render(
  <React.StrictMode>
    <BrowserRouter>
      <AuthProvider>
        <App />
      </AuthProvider>
    </BrowserRouter>
  </React.StrictMode>,
)

// Registers the service worker (public/sw.js) so the browser can offer
// "Install App" for ShilpSetu. Wrapped in a feature check + try/catch
// so it never breaks the app on browsers that don't support it.
if ('serviceWorker' in navigator) {
  window.addEventListener('load', () => {
    navigator.serviceWorker.register('/sw.js').catch(() => {
      // Not fatal - the app still works fine without the service worker,
      // it just won't be installable on this browser.
    })
  })
}

import { useEffect, useRef, useState } from 'react'
import { listProducts } from '../services/api.js'
import VoiceInput from '../components/VoiceInput.jsx'
import { sendBusinessMessage, getChatHistory } from '../services/api.js'
import { useAuth } from '../services/AuthContext.jsx'

const SUGGESTED_QUESTIONS = [
  'How should I promote this product?',
  'Who could be my customers?',
  'How should I package this product?',
  'What makes my product unique?',
  'How can I sell this product online?',
  'How should I prepare for B2B selling?',
]

export default function BusinessManager() {
  const { token, user } = useAuth()
  const [products, setProducts] = useState([])
  const [productId, setProductId] = useState('')
  const [messages, setMessages] = useState([])
  const [input, setInput] = useState('')
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')
  const bottomRef = useRef(null)

  useEffect(() => {
    listProducts(token).then(setProducts).catch(() => {})
  }, [token])

  useEffect(() => {
    getChatHistory(token, productId || undefined)
      .then((history) => setMessages(history.map((m) => ({ role: m.role, text: m.message }))))
      .catch(() => {})
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [productId])

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' })
  }, [messages])

  async function sendMessage(text) {
    const message = text ?? input
    if (!message.trim()) return

    setMessages((prev) => [...prev, { role: 'user', text: message }])
    setInput('')
    setError('')
    setLoading(true)
    try {
      const data = await sendBusinessMessage({ message, product_id: productId || undefined }, token)
      setMessages((prev) => [...prev, { role: 'assistant', text: data.reply, aiMode: data.ai_mode, aiProviderLabel: data.ai_provider_label }])
    } catch (err) {
      setError(err.message)
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="flex flex-col" style={{ minHeight: 'calc(100vh - 64px - 64px)' }}>
      <div className="p-3 bg-white border-b border-gray-200">
        <label className="text-xs text-gray-500 block mb-1">Talking about (optional)</label>
        <select
          className="w-full p-2 rounded-lg border border-gray-300 text-sm"
          value={productId}
          onChange={(e) => setProductId(e.target.value)}
        >
          <option value="">General business advice</option>
          {products.map((p) => (
            <option key={p.id} value={p.id}>{p.name}</option>
          ))}
        </select>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-3">
        {messages.length === 0 && (
          <p className="text-center text-gray-400 text-sm mt-6">
            👋 Ask me anything about promoting, pricing or selling your craft.
          </p>
        )}

        {messages.map((m, i) => (
          <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div
              className={`max-w-[80%] rounded-2xl px-4 py-2 text-sm ${
                m.role === 'user' ? 'bg-forest text-white' : 'bg-white shadow-sm text-charcoal'
              }`}
            >
              {m.text}
              {m.role === 'assistant' && m.aiMode === 'demo' && (
                <p className="text-[10px] text-sand font-semibold mt-1">Demo Mode reply</p>
              )}
              {m.role === 'assistant' && m.aiMode === 'real' && m.aiProviderLabel && (
                <p className="text-[10px] text-gray-400 mt-1">Answered by {m.aiProviderLabel}</p>
              )}
            </div>
          </div>
        ))}
        <div ref={bottomRef} />
      </div>

      <div className="p-3 bg-white border-t border-gray-200">
        <div className="flex gap-2 overflow-x-auto pb-2 mb-2">
          {SUGGESTED_QUESTIONS.map((q) => (
            <button
              key={q}
              onClick={() => sendMessage(q)}
              className="whitespace-nowrap text-xs bg-ivory border border-sand text-charcoal px-3 py-1.5 rounded-full"
            >
              {q}
            </button>
          ))}
        </div>

        {error && <p className="text-red-600 text-xs mb-2">{error}</p>}

        <VoiceInput
          language={user?.preferred_language || 'Hindi'}
          label="Ask by voice"
          showLanguagePicker={false}
          onTranscript={(t) => setInput((current) => (current ? `${current} ${t}` : t))}
          className="mb-2"
        />

        <div className="flex gap-2">
          <input
            className="flex-1 p-3 rounded-full border border-gray-300 text-base"
            placeholder="Type or speak your question..."
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && sendMessage()}
          />
          <button
            onClick={() => sendMessage()}
            disabled={loading}
            className="bg-terracotta text-white px-5 rounded-full font-semibold disabled:opacity-60"
          >
            {loading ? '...' : 'Send'}
          </button>
        </div>
      </div>
    </div>
  )
}

import { useState } from 'react'
import ProductPicker from '../components/ProductPicker.jsx'
import VoiceInput from '../components/VoiceInput.jsx'
import { generateCatalogue, updateProduct } from '../services/api.js'
import { useAuth } from '../services/AuthContext.jsx'

export default function Catalogue() {
  const { token, user } = useAuth()
  const language = user?.preferred_language || 'Hindi'

  const [product, setProduct] = useState(null)
  const [rawText, setRawText] = useState('')

  const [result, setResult] = useState(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')
  const [saved, setSaved] = useState(false)

  // Speech arrives phrase by phrase, so we add to what is already there
  // instead of overwriting it.
  function appendSpoken(text) {
    setRawText((current) => (current ? `${current} ${text}` : text))
  }

  async function handleGenerate() {
    if (!rawText.trim()) {
      setError('Please speak or type something about your product first.')
      return
    }
    setError('')
    setLoading(true)
    try {
      const data = await generateCatalogue(
        {
          raw_text: rawText,
          product_name: product?.name,
          category: product?.category,
          material: product?.material,
          craft_type: product?.craft_type,
          language,
        },
        token
      )
      setResult(data)
      setSaved(false)
    } catch (err) {
      setError(err.message)
    } finally {
      setLoading(false)
    }
  }

  function updateField(field, value) {
    setResult({ ...result, [field]: value })
  }

  async function handleSave() {
    if (!result || !product) return
    setLoading(true)
    setError('')
    try {
      const formData = new FormData()
      formData.append('name', result.title_english || product.name)
      formData.append('name_hindi', result.title_hindi || product.name_hindi || '')
      formData.append('description_english', result.description_english || '')
      formData.append('description_hindi', result.description_hindi || '')
      formData.append('material', result.material || product.material || '')
      formData.append('category', result.category || product.category || '')
      formData.append('craft_type', product.craft_type || '')
      formData.append('price', product.price ?? '')
      formData.append('status', product.status)

      const updated = await updateProduct(product.id, formData, token)
      setProduct(updated)
      setSaved(true)
    } catch (err) {
      setError(err.message)
    } finally {
      setLoading(false)
    }
  }

  const inputClass = 'w-full p-3 rounded-lg border border-gray-300 focus:border-forest focus:outline-none text-base'
  const labelClass = 'block text-sm font-medium text-charcoal mb-1 mt-4'

  return (
    <div>
      <ProductPicker selectedId={product?.id} onSelect={(p) => { setProduct(p); setResult(null) }} />

      {product && (
        <div className="p-5">
          <div className="bg-white rounded-xl p-4 shadow-sm mb-4">
            <p className="text-sm font-medium text-charcoal mb-2">
              🎙️ Speak about your product — no typing needed
            </p>
            <VoiceInput
              language={language}
              label="Speak About Your Product"
              onTranscript={appendSpoken}
              className="mb-3"
            />

            <label className={labelClass}>⌨️ Type About Your Product</label>
            <textarea
              className={inputClass}
              rows={4}
              value={rawText}
              onChange={(e) => setRawText(e.target.value)}
              placeholder="Or type here in Hindi, Hinglish or English..."
            />

            {error && <p className="text-red-600 text-sm mt-3">{error}</p>}

            <button
              onClick={handleGenerate}
              disabled={loading}
              className="w-full bg-terracotta text-white font-semibold py-3 rounded-full mt-4 shadow-md disabled:opacity-60"
            >
              {loading ? 'Generating catalogue...' : '✨ Create Catalogue with AI'}
            </button>
          </div>

          {result && (
            <div className="bg-white rounded-xl p-4 shadow-sm">
              <div className="flex items-center justify-between mb-3">
                <h3 className="font-semibold text-forest">Review &amp; Edit</h3>
                <span className={`text-xs font-semibold px-2 py-1 rounded-full ${result.ai_mode === 'real' ? 'bg-forest text-white' : 'bg-sand text-charcoal'}`}>
                  {result.ai_mode === 'real' ? `${result.ai_provider_label || 'AI'} Generated` : 'Demo Mode'}
                </span>
              </div>
              {result.ai_mode !== 'real' && (
                <p className="text-xs text-gray-500 mb-3">
                  No AI API key is configured yet, so this is a template-based draft, not a real
                  AI translation — please review the text carefully before publishing.
                </p>
              )}

              <label className={labelClass}>Title (English)</label>
              <input className={inputClass} value={result.title_english || ''} onChange={(e) => updateField('title_english', e.target.value)} />

              <label className={labelClass}>Title ({language})</label>
              <input className={inputClass} value={result.title_hindi || ''} onChange={(e) => updateField('title_hindi', e.target.value)} />

              <label className={labelClass}>Description (English)</label>
              <textarea className={inputClass} rows={3} value={result.description_english || ''} onChange={(e) => updateField('description_english', e.target.value)} />

              <label className={labelClass}>Description ({language})</label>
              <textarea className={inputClass} rows={3} value={result.description_hindi || ''} onChange={(e) => updateField('description_hindi', e.target.value)} />

              <label className={labelClass}>Key Features</label>
              <p className="text-sm text-gray-700 bg-ivory rounded-lg p-3">{(result.features || []).join(' • ')}</p>

              <label className={labelClass}>Marketing Caption</label>
              <input className={inputClass} value={result.marketing_caption || ''} onChange={(e) => updateField('marketing_caption', e.target.value)} />

              <label className={labelClass}>Social Media Caption</label>
              <input className={inputClass} value={result.social_caption || ''} onChange={(e) => updateField('social_caption', e.target.value)} />

              {saved && <p className="text-forest text-sm mt-3">Saved to product ✓</p>}

              <button
                onClick={handleSave}
                disabled={loading}
                className="w-full bg-forest text-white font-semibold py-3 rounded-full mt-4 shadow-md disabled:opacity-60"
              >
                {loading ? 'Saving...' : 'Save to Product'}
              </button>
            </div>
          )}
        </div>
      )}
    </div>
  )
}
